///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf91100_reportresult";
scwin.crtvl_sf1 = undefined;
scwin.crtvl_sf2 = undefined;
scwin.crtvl_sf3 = undefined;
scwin.crtvl_sf4 = undefined;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — crtvlList, param.method, callList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf91100_reportresult.onpageload' });
    }
};

/**
