 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_cd", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cd"); })() === '9201'); } }, { id: "if_cd_2", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cd"); })() === '9202'); } }, { id: "if_cd_3", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cd"); })() === '9203'); } }, { id: "if_cd_4", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cd"); })() === '9204'); } }, { id: "if_crtvlList", fn: function(){ return (!(String(((dma_pageContext.get("crtvlList") ?? "")) === null ? '' : ((dma_pageContext.get("crtvlList") ?? ""))).length === 0)); } }, { id: "if_coupnRtFinalYn_txt", fn: function(){ return ((dma_map.get("coupnRtFinalYn") ?? (() => { throw new Error("unresolved:" + "map.coupnRtFinalYn"); })()) === 'Y'); } }, { id: "if_coupnRtFinalYn_2_txt", fn: function(){ return ((dma_map.get("coupnRtFinalYn") ?? (() => { throw new Error("unresolved:" + "map.coupnRtFinalYn"); })()) !== 'Y'); } }, { id: "if_infllnkYn_txt", fn: function(){ return ((dma_map.get("infllnkYn") ?? (() => { throw new Error("unresolved:" + "map.infllnkYn"); })()) === 'Y'); } }, { id: "if_infllnkYn_2_txt", fn: function(){ return ((dma_map.get("infllnkYn") ?? (() => { throw new Error("unresolved:" + "map.infllnkYn"); })()) !== 'Y'); } }, { id: "if_hbrdbndYn_txt", fn: function(){ return ((dma_map.get("hbrdbndYn") ?? (() => { throw new Error("unresolved:" + "map.hbrdbndYn"); })()) === 'Y'); } }, { id: "if_hbrdbndYn_2_txt", fn: function(){ return ((dma_map.get("hbrdbndYn") ?? (() => { throw new Error("unresolved:" + "map.hbrdbndYn"); })()) !== 'Y'); } }, { id: "if_crtvlSf1_txt", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.crtvl_sf1 !== "undefined" && scwin.crtvl_sf1 !== null ? scwin.crtvl_sf1 : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "crtvl_sf1" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("crtvl_sf1")) === 'Y'); } }, { id: "if_crtvlSf2_txt", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.crtvl_sf2 !== "undefined" && scwin.crtvl_sf2 !== null ? scwin.crtvl_sf2 : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "crtvl_sf2" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("crtvl_sf2")) === 'Y'); } }, { id: "if_crtvlSf3_txt", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.crtvl_sf3 !== "undefined" && scwin.crtvl_sf3 !== null ? scwin.crtvl_sf3 : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "crtvl_sf3" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("crtvl_sf3")) === 'Y'); } }, { id: "if_crtvlSf4_txt", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.crtvl_sf4 !== "undefined" && scwin.crtvl_sf4 !== null ? scwin.crtvl_sf4 : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "crtvl_sf4" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("crtvl_sf4")) === 'Y'); } }, { id: "c_when_28", fn: function(){ return ((dma_pageContext.get("method") ?? "")==='srchReport3'); } }, { id: "if_callList", fn: function(){ return (!(String(((dma_pageContext.get("callList") ?? "")) === null ? '' : ((dma_pageContext.get("callList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

